    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the agreement to arbitrate, either party may seek temporary, preliminary, or permanent injunctive relief, specific performance, or other equitable remedies in any court of competent jurisdiction to protect its rights pending arbitration or to enforce arbitration outcomes.', ARRAY['notwithstanding','agreement to arbitrate','either party','seek','temporary','preliminary','permanent','injunctive relief','specific performance','equitable remedies','court','competent jurisdiction','protect','rights','pending arbitration','enforce','arbitration outcomes']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Standard injunctive relief carveout", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard carveout preserving access to courts for injunctive and equitable relief. Essential for protecting IP rights, confidentiality, and other interests requiring immediate action."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The parties acknowledge that breach of confidentiality, publicity, or intellectual property provisions may cause irreparable harm for which monetary damages would be inadequate. Amazon shall be entitled to seek injunctive relief without proof of actual damages or posting of bond.', ARRAY['acknowledge','breach','confidentiality','publicity','intellectual property','irreparable harm','monetary damages','inadequate','Amazon','entitled','seek injunctive relief','without proof','actual damages','posting of bond']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Irreparable harm acknowledgment with bond waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Irreparable harm acknowledgment supports injunction motions. Bond waiver removes practical barrier to obtaining emergency relief."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may seek a temporary restraining order or preliminary injunction in any court of competent jurisdiction without first demanding arbitration. The court''s order shall remain in effect until the arbitrator issues a superseding order or final award.', ARRAY['Amazon','seek','temporary restraining order','preliminary injunction','court','competent jurisdiction','without first','demanding arbitration','court''s order','remain in effect','arbitrator','issues','superseding order','final award']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "TRO/PI without arbitration demand", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Pre-arbitration TRO/PI access is essential for emergencies. Court order effectiveness until arbitrator supersedes provides continuous protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The arbitrator shall have authority to issue preliminary injunctive relief and other provisional remedies. However, such authority shall not limit either party''s right to seek such relief from a court of competent jurisdiction at any time before or during arbitration.', ARRAY['arbitrator','authority','issue','preliminary injunctive relief','provisional remedies','not limit','either party''s right','seek','relief','court','competent jurisdiction','any time','before','during arbitration']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Dual arbitrator and court authority", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Parallel arbitrator and court authority for provisional relief provides maximum flexibility. Party can choose most effective forum for emergency relief."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Seeking injunctive relief in court shall not waive the right to arbitrate the underlying dispute. Following issuance of any injunction, the parties shall proceed to arbitration for determination of all claims on the merits.', ARRAY['seeking','injunctive relief','court','not waive','right to arbitrate','underlying dispute','following','issuance','injunction','parties','proceed','arbitration','determination','claims','merits']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "No waiver of arbitration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarifies that court action for injunctive relief doesn''t waive arbitration for merits. Preserves arbitration for substantive dispute resolution."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may seek specific performance of ProdCo''s delivery obligations, grant of rights provisions, and any other obligations for which legal remedies would be inadequate. ProdCo consents to such specific performance and waives any defense that legal remedies are adequate.', ARRAY['Amazon','seek','specific performance','ProdCo''s delivery obligations','grant of rights','obligations','legal remedies','inadequate','ProdCo consents','specific performance','waives','defense','legal remedies','adequate']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Specific performance with defense waiver", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific performance availability for key obligations with defense waiver ensures Amazon can compel performance rather than accept damages."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The court or arbitrator may issue such orders as necessary to preserve the status quo pending resolution, including orders to: (a) maintain confidentiality; (b) preserve evidence; (c) prevent dissipation of assets; and (d) prevent irreparable harm.', ARRAY['court','arbitrator','issue','orders','preserve','status quo','pending resolution','maintain confidentiality','preserve evidence','prevent dissipation','assets','prevent','irreparable harm']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Status quo preservation orders", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Enumerated status quo preservation orders clarify scope of available interim relief. Addresses key protection needs during dispute resolution."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Either party may seek injunctive relief in court. The party seeking relief shall provide the other party with reasonable advance notice of any motion for injunctive relief, except where such notice would render the relief ineffective.', ARRAY['either party','seek','injunctive relief','court','party','seeking relief','provide','other party','reasonable advance notice','motion','injunctive relief','except','notice','render','relief','ineffective']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Advance notice with exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Advance notice requirement with effectiveness exception is balanced approach. Allows preparation while preserving emergency relief capability."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Injunctive relief may be sought in court. If a court issues preliminary relief, either party may request that the arbitrator review and modify such relief as appropriate. The arbitrator''s modification shall supersede the court''s order.', ARRAY['injunctive relief','sought','court','court issues','preliminary relief','either party','request','arbitrator','review','modify','relief','appropriate','arbitrator''s modification','supersede','court''s order']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Arbitrator review of court relief", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Arbitrator review of court-issued relief allows for reassessment in arbitration context. Provides path to modify relief as circumstances develop."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may seek emergency arbitrator relief under JAMS rules as an alternative to court proceedings. Emergency arbitrator proceedings shall not preclude subsequent court action if the emergency arbitrator''s order proves insufficient.', ARRAY['Amazon','seek','emergency arbitrator relief','JAMS rules','alternative','court proceedings','emergency arbitrator proceedings','not preclude','subsequent court action','emergency arbitrator''s order','insufficient']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Emergency arbitrator option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Emergency arbitrator as alternative to court provides additional option. Non-preclusion of court action if insufficient preserves full remedies."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The injunctive relief carveout applies to both parties. However, ProdCo shall not seek injunctive relief to prevent Amazon from exercising its termination rights or to compel Amazon to continue production or release the Program.', ARRAY['injunctive relief carveout','applies','both parties','ProdCo','not seek','injunctive relief','prevent','Amazon','exercising','termination rights','compel','Amazon','continue production','release','Program']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Limits on ProdCo injunctive relief", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout preventing ProdCo from enjoining Amazon''s termination or release decisions protects Amazon''s operational discretion."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Injunctive relief is available. If either party obtains injunctive relief and is subsequently found not to have been entitled to such relief, such party shall indemnify the other for losses caused by the wrongfully obtained injunction.', ARRAY['injunctive relief','available','either party','obtains','injunctive relief','subsequently found','not entitled','such relief','party','indemnify','other','losses caused','wrongfully obtained','injunction']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Wrongful injunction indemnity", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Wrongful injunction indemnity is common counterbalance to injunctive relief access. May be acceptable given bond waiver benefit."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Court jurisdiction for injunctive relief shall be exclusive to the courts specified in the venue provision. Neither party may seek injunctive relief in any other court without the other''s consent.', ARRAY['court jurisdiction','injunctive relief','exclusive','courts','specified','venue provision','neither party','seek','injunctive relief','other court','without','other''s consent']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Venue-limited injunctive relief", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Venue limitation on injunctive relief may be acceptable if primary venue courts are available. Limits forum shopping for emergency relief."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties agree that disputes shall be resolved exclusively by arbitration. Neither party may seek injunctive or other equitable relief from any court, and the arbitrator shall have exclusive authority over all remedies.', ARRAY['disputes','resolved exclusively','arbitration','neither party','seek','injunctive','equitable relief','court','arbitrator','exclusive authority','all remedies']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "No court access for injunctive relief", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Eliminating court access for injunctive relief is unacceptable. Arbitration may be too slow for emergencies; court access for provisional remedies must be preserved."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Either party may seek injunctive relief in court. However, the party seeking relief must first obtain the arbitrator''s permission, which the arbitrator may grant or deny in its discretion.', ARRAY['either party','seek','injunctive relief','court','party','seeking relief','first obtain','arbitrator''s permission','arbitrator','grant','deny','discretion']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Arbitrator permission required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring arbitrator permission for court relief defeats emergency relief purpose. Court access must be immediately available without arbitrator involvement."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may seek injunctive relief in court only after providing ProdCo with thirty (30) days'' advance written notice and an opportunity to cure the alleged violation.', ARRAY['Amazon','seek','injunctive relief','court','only after','providing','ProdCo','thirty days','advance written notice','opportunity','cure','alleged violation']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "30-day notice requirement for injunctive relief", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "30-day notice requirement defeats purpose of injunctive relief for emergencies. Irreparable harm often occurs immediately; notice delay is unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The injunctive relief carveout is mutual. ProdCo may seek injunctive relief to compel Amazon to continue production, make scheduled payments, or proceed with release of the Program as planned.', ARRAY['injunctive relief carveout','mutual','ProdCo','seek','injunctive relief','compel','Amazon','continue production','make scheduled payments','proceed','release','Program','planned']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo injunctive relief to compel Amazon", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo injunctive relief to compel Amazon performance would override Amazon''s termination and release discretion. Such compelled performance is inappropriate."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Injunctive relief is available. However, if the party seeking relief does not ultimately prevail on the merits in arbitration, such party shall pay the other party''s attorneys'' fees incurred in opposing the injunction motion.', ARRAY['injunctive relief','available','party','seeking relief','not ultimately prevail','merits','arbitration','pay','other party''s','attorneys'' fees','incurred','opposing','injunction motion']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Fee shifting for unsuccessful merits", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Fee shifting based on merits outcome creates significant disincentive to seek legitimate emergency relief. Injunctive relief decision should be evaluated independently of merits."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Injunctive relief may be sought only for violations of the confidentiality provisions. All other disputes, including intellectual property claims, shall be resolved exclusively by arbitration without access to court remedies.', ARRAY['injunctive relief','sought','only','violations','confidentiality provisions','other disputes','intellectual property claims','resolved exclusively','arbitration','without access','court remedies']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Confidentiality-only injunctive relief", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Limiting injunctive relief to confidentiality excludes critical areas like IP infringement. Injunctive relief must be available for all appropriate circumstances."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Before initiating arbitration, the parties shall attempt to resolve the dispute through good faith negotiations. Within ten (10) business days of a party''s written dispute notice, executives with settlement authority shall meet (in person or by video) to attempt resolution.', ARRAY['before initiating','arbitration','parties','attempt','resolve','dispute','good faith negotiations','ten business days','party''s','written dispute notice','executives','settlement authority','meet','in person','video','attempt resolution']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Executive negotiation requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Executive negotiation requirement is reasonable pre-arbitration step. Ten-day timeline prevents extended delay. Settlement authority requirement ensures meaningful discussion."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The informal resolution period shall not exceed thirty (30) days from the date of the dispute notice. If resolution is not achieved within such period, either party may proceed to arbitration. The parties may mutually agree in writing to extend the negotiation period.', ARRAY['informal resolution period','not exceed','thirty days','date','dispute notice','resolution','not achieved','period','either party','proceed','arbitration','mutually agree','writing','extend','negotiation period']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "30-day negotiation cap", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "30-day cap prevents indefinite delay while allowing meaningful negotiation. Extension by mutual agreement provides flexibility without unilateral delay."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The informal resolution requirement shall not apply to: (a) claims requiring immediate injunctive relief; (b) claims where the statute of limitations would expire during the resolution period; or (c) claims where delay would cause irreparable harm.', ARRAY['informal resolution requirement','not apply','claims','immediate injunctive relief','claims','statute of limitations','expire','resolution period','claims','delay','cause','irreparable harm']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Exceptions to informal resolution", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Exceptions for time-sensitive matters ensure negotiation requirement doesn''t prejudice urgent claims. Essential carveouts for practical operation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Participation in informal resolution shall not waive any party''s claims or defenses, toll any limitations period, or be admissible as evidence in any subsequent proceeding. All discussions shall be treated as compromise negotiations under applicable evidence rules.', ARRAY['participation','informal resolution','not waive','claims','defenses','toll','limitations period','not admissible','evidence','subsequent proceeding','discussions','treated','compromise negotiations','applicable evidence rules']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "No waiver and confidentiality", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "No waiver and evidence protection for settlement discussions encourages candid negotiation. Standard treatment as compromise negotiations protects both parties."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For disputes involving alleged breach of payment obligations, the parties shall engage a mutually agreed accounting firm to review the disputed calculations before proceeding to arbitration. The accountant''s determination shall be advisory and non-binding.', ARRAY['disputes','alleged breach','payment obligations','engage','mutually agreed','accounting firm','review','disputed calculations','before','proceeding','arbitration','accountant''s determination','advisory','non-binding']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Expert review for payment disputes", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Expert accounting review for payment disputes can narrow issues before arbitration. Advisory/non-binding status preserves parties'' rights while adding informed perspective."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notice of a dispute shall include: (a) a description of the dispute; (b) identification of the Agreement provisions at issue; (c) the remedy sought; and (d) the name and contact information of the executive designated to participate in resolution discussions.', ARRAY['notice','dispute','include','description','dispute','identification','Agreement provisions','issue','remedy sought','name','contact information','executive','designated','participate','resolution discussions']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Dispute notice requirements", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific notice requirements ensure receiving party has sufficient information to prepare for meaningful discussion. Executive identification enables prompt scheduling."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Failure to participate in good faith in the informal resolution process shall not bar the non-participating party from arbitration, but the arbitrator may consider such failure in allocating costs and fees.', ARRAY['failure','participate','good faith','informal resolution','not bar','non-participating party','arbitration','arbitrator','consider','failure','allocating costs','fees']::text[], '{"doc": "PSA_Principal_Terms", "section": "Dispute Resolution", "note": "Cost consequences for non-participation", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Non-participation doesn''t bar arbitration (preserving access to remedy) but has cost consequences. Incentivizes good faith participation without creating procedural trap."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Before arbitration, the parties shall engage in a three-tier escalation process: (1) project-level representatives (10 days); (2) department heads (10 days); (3) executives with settlement authority (10 days). Each tier must be exhausted before proceeding to the next.', ARRAY['before arbitration','three-tier','escalation process','project-level representatives','10 days','department heads','10 days','executives','settlement authority','10 days','tier','exhausted','proceeding','next']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Three-tier escalation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Three-tier escalation totaling 30 days may be acceptable if exceptions for urgent matters are preserved. Structured escalation can effectively resolve disputes without arbitration."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The parties shall attempt good faith resolution before arbitration. If the dispute is not resolved within 30 days, either party may request non-binding mediation with JAMS before proceeding to arbitration. Mediation shall not exceed 30 additional days.', ARRAY['attempt','good faith resolution','before arbitration','dispute','not resolved','30 days','either party','request','non-binding mediation','JAMS','before','proceeding','arbitration','mediation','not exceed','30 additional days']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Optional mediation step", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Optional mediation as additional step may be acceptable given voluntary nature. 30-day cap prevents indefinite delay. Either party can proceed to arbitration if mediation fails."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Informal resolution discussions shall be conducted in person at a mutually convenient location, or by video conference if in-person meeting is not feasible within the required timeframe. Telephone-only discussions shall not satisfy the requirement.', ARRAY['informal resolution discussions','conducted','in person','mutually convenient location','video conference','in-person meeting','not feasible','required timeframe','telephone-only discussions','not satisfy','requirement']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Meeting format requirements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "In-person or video meeting requirement promotes substantive engagement. Telephone exclusion ensures more formal discussion. Flexibility for feasibility is practical."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The informal resolution period shall toll any applicable statutes of limitations and contractual deadlines. Upon conclusion of the informal period without resolution, such limitations shall resume from where they were tolled.', ARRAY['informal resolution period','toll','applicable statutes of limitations','contractual deadlines','conclusion','informal period','without resolution','limitations','resume','where','tolled']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Tolling during informal period", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tolling during informal resolution eliminates statute of limitations concern and encourages good faith negotiation without time pressure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'For creative disputes regarding the direction of the Program, the parties shall first seek resolution through their respective heads of creative development before invoking the dispute resolution process. Such creative discussion shall precede any formal dispute notice.', ARRAY['creative disputes','direction','Program','seek resolution','heads of creative development','before invoking','dispute resolution process','creative discussion','precede','formal dispute notice']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Creative-specific pre-escalation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Creative-specific preliminary step recognizes unique nature of creative disputes and appropriate internal contacts. Keeps creative disagreements at appropriate level before escalation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Any settlement reached during informal resolution shall be memorialized in a written settlement agreement signed by both parties. Oral agreements or agreements not reduced to writing shall not be binding.', ARRAY['settlement','during','informal resolution','memorialized','written settlement agreement','signed','both parties','oral agreements','agreements','not reduced to writing','not binding']::text[], '{"doc": "Counterparty_Markup", "section": "Dispute Resolution", "note": "Written settlement requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Written settlement requirement ensures clarity on terms and prevents disputes about what was agreed. Standard practice for meaningful settlements."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Before initiating arbitration, the parties shall engage in mandatory mediation with a JAMS mediator for a minimum of three (3) full-day sessions. Arbitration may not be commenced until mediation is complete.', ARRAY['before initiating','arbitration','mandatory mediation','JAMS mediator','minimum','three','full-day sessions','arbitration','not be commenced','until','mediation','complete']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Mandatory three-day mediation", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Mandatory three-day mediation is excessive prerequisite that delays access to binding resolution. Reasonable negotiation is appropriate; extended mandatory mediation is not."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The parties shall engage in informal resolution for a minimum of ninety (90) days before either party may initiate arbitration. This period may not be shortened by either party unilaterally.', ARRAY['engage','informal resolution','minimum','ninety days','before','either party','initiate arbitration','period','not be shortened','either party','unilaterally']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "90-day mandatory negotiation", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "90-day mandatory negotiation is excessive delay to binding resolution. 30 days maximum is acceptable; 90 days prevents timely dispute resolution."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Informal resolution is mandatory for all disputes. If a party initiates arbitration without completing the informal resolution process, the arbitration shall be dismissed and the filing party shall pay the other party''s attorneys'' fees.', ARRAY['informal resolution','mandatory','all disputes','party','initiates arbitration','without completing','informal resolution process','arbitration','dismissed','filing party','pay','other party''s','attorneys'' fees']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Dismissal and fees for non-compliance", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Dismissal and fee shifting for informal resolution non-compliance is excessive remedy that could trap claims. Non-compliance should affect costs, not bar access to arbitration."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The informal resolution requirement applies to all disputes including claims for injunctive relief. Amazon may not seek emergency relief from any court or arbitrator until the informal resolution period has been exhausted.', ARRAY['informal resolution requirement','applies','all disputes','including','claims','injunctive relief','Amazon','not seek','emergency relief','court','arbitrator','until','informal resolution period','exhausted']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "No exception for injunctive relief", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Applying informal resolution to injunctive relief claims defeats emergency relief purpose. Clear exception for injunctive and emergency relief is essential."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'During the informal resolution period, the parties shall maintain the status quo and continue all performance obligations. Neither party may suspend performance or exercise any termination rights during such period.', ARRAY['during','informal resolution period','maintain','status quo','continue','all performance obligations','neither party','suspend performance','exercise','termination rights','during','period']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "Suspension of termination rights", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Suspending termination rights during informal resolution prevents Amazon from acting on material breach. Termination rights must remain available regardless of dispute status."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The informal resolution process shall be administered by an independent mediator selected by ProdCo and paid for by Amazon. The mediator shall have authority to issue non-binding recommendations that the parties must consider in good faith.', ARRAY['informal resolution process','administered','independent mediator','selected by ProdCo','paid for by Amazon','mediator','authority','issue','non-binding recommendations','parties','consider','good faith']::text[], '{"doc": "Counterparty_Proposal", "section": "Dispute Resolution", "note": "ProdCo-selected, Amazon-funded mediator", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "ProdCo selection with Amazon payment is one-sided. If mediation is included, mediator selection should be mutual and costs shared."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo may not assign, transfer, delegate, or otherwise dispose of this Agreement or any of its rights or obligations hereunder, whether by operation of law or otherwise, without Amazon''s prior written consent, which Amazon may withhold in its sole discretion. Any purported assignment without such consent shall be null and void.', ARRAY['ProdCo','not assign','transfer','delegate','dispose','Agreement','rights','obligations','operation of law','otherwise','Amazon''s prior written consent','withhold','sole discretion','purported assignment','without consent','null and void']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Standard ProdCo assignment restriction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive assignment restriction covering all transfer types including by operation of law. Sole discretion withholding and nullity for violations provides complete protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may freely assign, transfer, or delegate this Agreement or any of its rights or obligations hereunder, in whole or in part, to any affiliate, successor, or acquirer, or in connection with any merger, acquisition, reorganization, or sale of all or substantially all of Amazon''s assets, without ProdCo''s consent.', ARRAY['Amazon','freely assign','transfer','delegate','Agreement','rights','obligations','whole','part','affiliate','successor','acquirer','merger','acquisition','reorganization','sale','substantially all','assets','without','ProdCo''s consent']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Amazon free assignment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Amazon free assignment right to affiliates, successors, and acquirers without consent is essential for corporate flexibility. Covers all common transaction types."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'For purposes of this Section, a ''change of control'' of ProdCo shall be deemed an assignment requiring Amazon''s consent. ''Change of control'' means: (a) sale of more than 50% of voting securities; (b) merger or consolidation where ProdCo is not the surviving entity; or (c) sale of all or substantially all assets.', ARRAY['change of control','ProdCo','deemed','assignment','Amazon''s consent','change of control means','sale','50%','voting securities','merger','consolidation','not surviving entity','sale','substantially all assets']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Change of control as assignment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Change of control treated as assignment ensures Amazon can vet new ownership. Clear definition covering equity sale, M&A, and asset sale provides comprehensive coverage."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall not grant any lien, security interest, or encumbrance on this Agreement, the Program, or any rights hereunder without Amazon''s prior written consent. Any such grant without consent shall be void and shall constitute a material breach.', ARRAY['ProdCo','not grant','lien','security interest','encumbrance','Agreement','Program','rights','Amazon''s prior written consent','grant','without consent','void','material breach']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "No encumbrance without consent", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Security interest restriction prevents ProdCo from encumbering Agreement or Program rights. Void grant plus material breach characterization provides strong protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement shall be binding upon and inure to the benefit of the parties and their respective permitted successors and assigns. Nothing in this Agreement shall confer upon any third party any rights or remedies.', ARRAY['Agreement','binding upon','inure','benefit','parties','permitted successors','assigns','nothing','Agreement','confer','third party','rights','remedies']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Binding on successors with no third-party rights", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard binding clause with ''permitted'' qualifier reinforcing assignment restrictions. No third-party beneficiary provision prevents claims by non-parties."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may assign its payment obligations to any creditworthy assignee without ProdCo''s consent. ProdCo may not look to Amazon for payment after such assignment if the assignee has expressly assumed such obligations in writing.', ARRAY['Amazon','assign','payment obligations','creditworthy assignee','without','ProdCo''s consent','ProdCo','not look to Amazon','payment','after assignment','assignee','expressly assumed','obligations','writing']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Payment obligation assignment with release", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Payment obligation assignment with creditworthiness requirement and written assumption provides appropriate protection for ProdCo while giving Amazon flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon may license, sublicense, or authorize third parties to exercise any of Amazon''s rights under this Agreement, including exploitation rights, without such license constituting an assignment. Amazon shall remain responsible for any licensee''s compliance with applicable Agreement terms.', ARRAY['Amazon','license','sublicense','authorize','third parties','exercise','Amazon''s rights','Agreement','exploitation rights','without','license','constituting','assignment','Amazon','remain responsible','licensee''s compliance','Agreement terms']::text[], '{"doc": "PSA_Principal_Terms", "section": "Assignment", "note": "Licensing versus assignment clarification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clarification that licensing is not assignment preserves Amazon''s exploitation flexibility. Continued Amazon responsibility for licensee compliance protects ProdCo."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo may not assign without Amazon''s consent, which shall not be unreasonably withheld for assignments to ProdCo''s wholly-owned subsidiaries, provided such subsidiary assumes all obligations and ProdCo remains jointly and severally liable.', ARRAY['ProdCo','not assign','Amazon''s consent','not unreasonably withheld','assignments','wholly-owned subsidiaries','subsidiary assumes','all obligations','ProdCo remains','jointly','severally liable']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Subsidiary assignment with continued liability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited ''not unreasonably withheld'' standard for wholly-owned subsidiary assignments with continued ProdCo liability may be acceptable. Provides operational flexibility without releasing ProdCo."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Assignment restrictions apply. Amazon agrees to provide written notice to ProdCo within thirty (30) days of any assignment by Amazon, identifying the assignee and the scope of assignment. Failure to provide notice shall not invalidate the assignment.', ARRAY['assignment restrictions','apply','Amazon','provide','written notice','ProdCo','thirty days','assignment','Amazon','identifying','assignee','scope','assignment','failure','provide notice','not invalidate','assignment']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Assignment notice requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Post-assignment notice requirement is reasonable transparency measure. Non-invalidation for notice failure preserves Amazon''s assignment effectiveness."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo requires Amazon consent for assignment. If Amazon does not respond to a written assignment request within thirty (30) days, Amazon shall be deemed to have denied the request. ProdCo may resubmit with additional information.', ARRAY['ProdCo requires','Amazon consent','assignment','Amazon','not respond','written assignment request','thirty days','deemed','denied','request','resubmit','additional information']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Deemed denial for non-response", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Deemed denial for non-response (rather than deemed approval) preserves Amazon''s control. Resubmission option provides path forward for ProdCo."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amazon may assign to affiliates. For purposes of this Agreement, ''affiliate'' means any entity that directly or indirectly controls, is controlled by, or is under common control with Amazon, where ''control'' means ownership of more than 50% of voting securities.', ARRAY['Amazon','assign','affiliates','affiliate means','entity','directly','indirectly','controls','controlled by','common control','Amazon','control means','ownership','50%','voting securities']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Affiliate definition", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear affiliate definition with 50% control threshold provides certainty on scope of Amazon''s affiliate assignment right. Standard corporate definition."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Upon any permitted assignment by ProdCo, the assignee shall execute an assumption agreement in form reasonably acceptable to Amazon. ProdCo shall provide a copy of such executed agreement to Amazon within ten (10) days of assignment.', ARRAY['permitted assignment','ProdCo','assignee','execute','assumption agreement','form','reasonably acceptable','Amazon','provide','copy','executed agreement','Amazon','ten days','assignment']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Assumption agreement requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Assumption agreement requirement ensures assignee is bound. Reasonable form acceptability standard and documentation timeline are appropriate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If Amazon assigns to an entity that is a direct competitor of ProdCo in the production business, Amazon shall provide ProdCo with reasonable advance notice. Assignment to a competitor shall not release Amazon from confidentiality obligations regarding ProdCo''s proprietary production methods.', ARRAY['Amazon assigns','entity','direct competitor','ProdCo','production business','provide','reasonable advance notice','assignment','competitor','not release','Amazon','confidentiality obligations','ProdCo''s proprietary','production methods']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Competitor assignment notice and confidentiality", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Competitor notice and maintained confidentiality for ProdCo proprietary methods addresses legitimate concern without restricting Amazon''s assignment right."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Neither party may assign this Agreement without the other party''s prior written consent. Assignment restrictions apply equally to Amazon and ProdCo, with consent not to be unreasonably withheld by either party.', ARRAY['neither party','assign','Agreement','without','other party''s','prior written consent','assignment restrictions','apply equally','Amazon','ProdCo','consent','not unreasonably withheld','either party']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "Mutual assignment restriction", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Mutual assignment restrictions limiting Amazon''s assignment right is unacceptable. Amazon requires free assignment to affiliates, successors, and in transactions."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon may not assign this Agreement to any competitor of ProdCo without ProdCo''s prior written consent. ''Competitor'' means any entity engaged in film or television production.', ARRAY['Amazon','not assign','Agreement','competitor','ProdCo','without','ProdCo''s prior written consent','competitor means','entity','engaged','film','television production']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "Competitor assignment restriction on Amazon", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Competitor restriction on Amazon''s assignment is unacceptable, especially with broad ''film or television production'' definition that would include most potential acquirers."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may freely assign this Agreement to any entity under common ownership or control with ProdCo without Amazon''s consent. Such assignment shall release ProdCo from all obligations under this Agreement.', ARRAY['ProdCo','freely assign','Agreement','entity','common ownership','control','ProdCo','without','Amazon''s consent','assignment','release ProdCo','all obligations']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "ProdCo free assignment with release", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo free assignment with release from obligations is completely unacceptable. Amazon must consent to any ProdCo assignment, and ProdCo should remain liable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If Amazon assigns this Agreement, ProdCo may elect to terminate this Agreement upon sixty (60) days'' notice and receive a termination payment equal to the remaining Production Fee.', ARRAY['Amazon assigns','Agreement','ProdCo','elect','terminate','Agreement','sixty days','notice','receive','termination payment','remaining Production Fee']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "ProdCo termination right upon Amazon assignment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Termination right with full payment upon Amazon assignment makes assignment economically prohibitive. Amazon must have unrestricted assignment without triggering termination."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Any assignment by Amazon shall require the assignee to assume all of Amazon''s obligations and to guarantee payment of all amounts that may become due to ProdCo. ProdCo shall have direct recourse against any assignee.', ARRAY['assignment','Amazon','require','assignee','assume','all','Amazon''s obligations','guarantee payment','amounts','due','ProdCo','direct recourse','against','assignee']::text[], '{"doc": "Counterparty_Markup", "section": "Assignment", "note": "Guarantee requirement for Amazon assignment", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Guarantee requirement for all Amazon assignments is inappropriate given creditworthiness of Amazon and typical assignees. Direct recourse against assignees creates ongoing obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Change of control of ProdCo shall not be deemed an assignment and shall not require Amazon''s consent, as ProdCo''s corporate transactions are independent of its contractual obligations.', ARRAY['change of control','ProdCo','not deemed','assignment','not require','Amazon''s consent','ProdCo''s corporate transactions','independent','contractual obligations']::text[], '{"doc": "Counterparty_Proposal", "section": "Assignment", "note": "Change of control not an assignment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Excluding change of control from assignment requirement allows ProdCo to be acquired by competitors or problematic parties without Amazon consent. Change of control must require consent."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'All notices required or permitted under this Agreement shall be in writing and shall be delivered: (a) personally; (b) by certified mail, return receipt requested; (c) by nationally recognized overnight courier; or (d) by email to the addresses set forth on the signature page, with a copy by one of the foregoing methods.', ARRAY['notices','required','permitted','Agreement','in writing','delivered','personally','certified mail','return receipt','nationally recognized','overnight courier','email','addresses','signature page','copy','foregoing methods']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Standard notice methods", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multiple acceptable notice methods with email requiring backup ensures both convenience and reliability. Standard commercial notice provision."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notices shall be deemed given: (a) when delivered personally; (b) three (3) business days after mailing by certified mail; (c) one (1) business day after deposit with overnight courier; or (d) when sent by email if confirmed by delivery by another method within two (2) business days.', ARRAY['notices','deemed given','delivered personally','three business days','mailing','certified mail','one business day','deposit','overnight courier','sent','email','confirmed','delivery','another method','two business days']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Notice effectiveness timing", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear deemed delivery timing for each method provides certainty. Email requiring confirmation addresses reliability concerns while permitting electronic initial delivery."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Either party may change its notice address by providing written notice to the other party in accordance with this Section. Address changes shall be effective upon receipt of such notice.', ARRAY['either party','change','notice address','providing','written notice','other party','accordance','Section','address changes','effective','receipt','notice']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Address change procedure", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard address change provision with effectiveness upon receipt. Allows parties to update contact information as needed."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notwithstanding the foregoing, routine operational communications, including scheduling, production updates, and administrative matters, may be made by email without backup delivery. Formal notices regarding breach, termination, dispute, or assignment shall comply with the formal notice requirements.', ARRAY['notwithstanding','routine operational communications','scheduling','production updates','administrative matters','email','without backup','formal notices','breach','termination','dispute','assignment','comply','formal notice requirements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Operational versus formal notice distinction", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Practical distinction between operational and formal notices. Email suffices for day-to-day matters; formal requirements for significant legal notices."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Notices to Amazon shall be sent to the Legal Department at the address specified on the signature page, with a copy to the Amazon business contact identified therein. Notices to ProdCo shall be sent to the address specified on the signature page, with a copy to ProdCo''s counsel if identified.', ARRAY['notices','Amazon','sent','Legal Department','address','signature page','copy','Amazon business contact','identified','notices','ProdCo','sent','address','signature page','copy','ProdCo''s counsel','identified']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Specific recipients with copies", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Clear identification of notice recipients with copy requirements ensures notices reach appropriate parties. Legal Department copy for Amazon ensures proper handling."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Any notice delivered to an incorrect address but which actually reaches the intended recipient shall be deemed effective upon actual receipt. Parties shall use good faith efforts to bring notice errors to the other party''s attention promptly.', ARRAY['notice','delivered','incorrect address','actually reaches','intended recipient','deemed effective','actual receipt','good faith efforts','notice errors','other party''s attention','promptly']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Actual receipt effectiveness", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Actual receipt provision ensures substance over form. Good faith error notification promotes cooperative relationship without formal requirements."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Refusal to accept delivery of a notice, or failure to maintain a valid notice address, shall not defeat the effectiveness of a notice properly sent to the last known address. In such cases, notice shall be deemed given when delivery is attempted.', ARRAY['refusal','accept delivery','notice','failure','maintain','valid notice address','not defeat','effectiveness','notice','properly sent','last known address','notice','deemed given','delivery','attempted']::text[], '{"doc": "PSA_Principal_Terms", "section": "Notices", "note": "Refusal and failed delivery", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Protection against delivery avoidance tactics. Deemed delivery upon attempted delivery to last known address prevents parties from evading notices."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Notices may be delivered by email alone if both parties have agreed in writing to accept email as the sole method of delivery for specified notice types. Such agreement may be revoked by either party upon ten (10) days'' written notice.', ARRAY['notices','delivered','email alone','both parties','agreed','writing','accept email','sole method','specified notice types','agreement','revoked','either party','ten days','written notice']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Email-only option by agreement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Optional email-only by mutual agreement provides flexibility while requiring affirmative consent. Revocation right preserves fall-back to formal methods."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'For time-sensitive notices where overnight courier would not achieve delivery within necessary timeframes, email notice shall be effective immediately upon transmission if the sender receives a delivery confirmation and the recipient does not object within two (2) hours.', ARRAY['time-sensitive notices','overnight courier','not achieve delivery','necessary timeframes','email notice','effective immediately','transmission','sender receives','delivery confirmation','recipient','not object','two hours']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Time-sensitive email exception", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Time-sensitive email exception with delivery confirmation and non-objection requirement addresses practical urgencies while maintaining some verification."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Notices regarding creative matters, production schedules, and delivery dates may be communicated through Amazon''s designated production management system. Communications through such system shall be deemed written notice for purposes of this Agreement.', ARRAY['notices','creative matters','production schedules','delivery dates','communicated','Amazon''s designated','production management system','communications','system','deemed','written notice','purposes','Agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Production system communications", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Production management system for operational notices streamlines communications. Limited to production matters, not formal legal notices."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'ProdCo shall maintain a notice address within the continental United States for purposes of receiving notices. If ProdCo is located outside the U.S., ProdCo shall designate a U.S. agent for service of notices.', ARRAY['ProdCo','maintain','notice address','continental United States','receiving notices','ProdCo','located outside','U.S.','designate','U.S. agent','service','notices']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "U.S. address requirement", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "U.S. address requirement for non-U.S. ProdCos simplifies notice delivery and ensures reliable receipt. Agent designation is standard for international parties."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'In the event of a dispute, notices related to such dispute shall be sent to both the party''s general notice address and to any counsel who has appeared for such party in connection with the dispute.', ARRAY['event','dispute','notices','related','dispute','sent','party''s general notice address','counsel','appeared','party','connection','dispute']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Dispute notice to counsel", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Copy to appearing counsel for dispute-related notices ensures legal team awareness. Addresses practical reality that counsel often handles dispute communications."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Either party may designate additional notice recipients (not to exceed three (3) per party) by written notice. Notice to all designated recipients shall be required for termination and breach notices only.', ARRAY['either party','designate','additional notice recipients','not exceed','three','per party','written notice','notice','all designated recipients','required','termination','breach notices','only']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Additional recipients for key notices", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Limited additional recipients with cap (three per party) for termination and breach notices is reasonable. Ensures critical notices reach key stakeholders."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Notices shall be effective only upon actual receipt by an officer or director of the receiving party. Delivery to any other person or address shall not constitute effective notice.', ARRAY['notices','effective','only','actual receipt','officer','director','receiving party','delivery','other person','address','not constitute','effective notice']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "Officer/director actual receipt required", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Officer/director actual receipt requirement makes notice delivery nearly impossible to confirm and allows avoidance. Standard deemed delivery rules are required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Notices must be delivered in person to a designated representative during business hours at the party''s principal place of business. Mail and courier delivery shall not constitute effective notice.', ARRAY['notices','delivered','in person','designated representative','business hours','principal place of business','mail','courier delivery','not constitute','effective notice']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "In-person only delivery", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "In-person only delivery is impractical and could enable notice avoidance. Standard mail, courier, and electronic methods must be acceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Notices from Amazon to ProdCo shall be effective upon delivery. Notices from ProdCo to Amazon shall not be effective unless and until acknowledged in writing by Amazon''s Legal Department.', ARRAY['notices','Amazon','ProdCo','effective','delivery','notices','ProdCo','Amazon','not effective','unless','until','acknowledged','writing','Amazon''s Legal Department']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "Asymmetric acknowledgment requirement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Requiring Amazon acknowledgment for ProdCo notice effectiveness creates massive asymmetry. Amazon could avoid notices indefinitely. Both parties'' notices must have equivalent effectiveness."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Notices shall be sent by email only to the email addresses specified herein. No other form of delivery shall be required or permitted. Email shall be deemed delivered when sent regardless of receipt.', ARRAY['notices','sent','email only','email addresses','specified','no other form','delivery','required','permitted','email','deemed delivered','when sent','regardless','receipt']::text[], '{"doc": "Counterparty_Markup", "section": "Notices", "note": "Email-only with sent equals delivered", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Email-only without backup and ''sent equals delivered'' regardless of receipt creates unreliable notice mechanism. Formal notices require more reliable delivery methods."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo may provide notice to Amazon by posting on ProdCo''s website and providing a link to such posting via email. Amazon shall be responsible for monitoring ProdCo''s website for notices.', ARRAY['ProdCo','provide notice','Amazon','posting','ProdCo''s website','providing','link','posting','email','Amazon','responsible','monitoring','ProdCo''s website','notices']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "Website posting notice", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Website posting as notice method is completely unacceptable. Notices must be delivered directly to recipients, not posted for them to find."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Any notice not objected to within five (5) business days of delivery shall be deemed accepted and binding on the receiving party. Failure to object shall constitute agreement to the contents of the notice.', ARRAY['notice','not objected to','five business days','delivery','deemed accepted','binding','receiving party','failure','object','constitute','agreement','contents','notice']::text[], '{"doc": "Counterparty_Proposal", "section": "Notices", "note": "Deemed acceptance of notice contents", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Deemed acceptance of notice contents is inappropriate. Notices communicate information; they don''t require response. This would create obligations based on non-response to any communication."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Neither party shall be liable for failure to perform its obligations (other than payment obligations) to the extent such failure results from a Force Majeure Event, provided that the affected party: (a) promptly notifies the other party; (b) uses reasonable efforts to mitigate the effects; and (c) resumes performance as soon as reasonably practicable.', ARRAY['neither party','liable','failure','perform','obligations','other than','payment obligations','extent','failure results','Force Majeure Event','affected party','promptly notifies','other party','reasonable efforts','mitigate','resumes performance','reasonably practicable']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "Standard FM clause with carveouts", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard force majeure provision with payment obligation exclusion and mitigation requirements. Reasonableness standard for resumption provides appropriate flexibility."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, '''Force Majeure Event'' means an event beyond a party''s reasonable control, including: acts of God; natural disasters; war, terrorism, or civil unrest; government actions or restrictions; labor strikes (except those involving only the affected party''s employees); and epidemics or pandemics.', ARRAY['Force Majeure Event','event','beyond','party''s reasonable control','acts of God','natural disasters','war','terrorism','civil unrest','government actions','restrictions','labor strikes','except','affected party''s employees','epidemics','pandemics']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "FM definition with enumeration", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive FM definition with enumerated events and reasonable control standard. Strike exception for party''s own employees prevents abuse. Pandemic inclusion is post-COVID standard."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Force Majeure Events shall not include: (a) changes in economic or market conditions; (b) fluctuations in currency exchange rates; (c) financial difficulties or insolvency; (d) changes in law that do not make performance illegal; or (e) events that were reasonably foreseeable at the time of contracting.', ARRAY['Force Majeure Events','not include','changes','economic','market conditions','fluctuations','currency exchange rates','financial difficulties','insolvency','changes in law','not make','performance illegal','events','reasonably foreseeable','time of contracting']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "FM exclusions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard exclusions preventing FM claims for economic hardship, financial problems, and foreseeable events. Ensures FM applies only to genuinely unforeseeable external events."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If a Force Majeure Event prevents performance for more than ninety (90) consecutive days, either party may terminate this Agreement upon thirty (30) days'' written notice. Upon such termination, Amazon shall pay for work performed through the termination date; no other amounts shall be due.', ARRAY['Force Majeure Event','prevents performance','ninety','consecutive days','either party','terminate','Agreement','thirty days','written notice','termination','Amazon','pay','work performed','termination date','no other amounts','due']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "Extended FM termination right", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Termination right after extended FM (90 days) provides exit for prolonged impossibility. Payment for work performed is fair; no additional payments limits exposure."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'During a Force Majeure Event affecting production, Amazon may, in its sole discretion: (a) suspend production and payments until the event concludes; (b) modify the production schedule; (c) relocate production; or (d) terminate the affected production and proceed with alternative arrangements.', ARRAY['during','Force Majeure Event','affecting production','Amazon','sole discretion','suspend','production','payments','event concludes','modify','production schedule','relocate production','terminate','affected production','proceed','alternative arrangements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "Amazon FM response options", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Multiple response options for Amazon during production FM provides flexibility. Sole discretion ensures Amazon controls response to events affecting its content."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Force majeure shall not excuse ProdCo from its obligations regarding: (a) ownership and grant of rights to Amazon; (b) indemnification obligations; (c) confidentiality obligations; (d) representations and warranties regarding completed work; or (e) cooperation with Amazon''s alternative arrangements.', ARRAY['force majeure','not excuse','ProdCo','obligations','ownership','grant of rights','Amazon','indemnification','confidentiality','representations','warranties','completed work','cooperation','Amazon''s alternative arrangements']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "Obligations not excused by FM", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Carving out key obligations from FM excuse ensures critical protections remain in place. Rights, indemnification, and confidentiality must not be suspended."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo shall maintain production insurance covering production interruption, cast coverage, and related force majeure risks. ProdCo shall use insurance proceeds first to resume production; any excess proceeds shall be applied as directed by Amazon.', ARRAY['ProdCo','maintain','production insurance','covering','production interruption','cast coverage','force majeure risks','use insurance proceeds','first','resume production','excess proceeds','applied','directed','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "Force Majeure", "note": "FM insurance requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "FM insurance requirement with proceeds application hierarchy protects against production interruption losses. Amazon direction on excess ensures proper allocation."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Force majeure applies. If a FM Event affects a Key Person (death, incapacity, unavailability), Amazon may elect to: (a) recast the role; (b) modify the Program; (c) suspend pending replacement; or (d) terminate. The parties shall consult in good faith on the appropriate response.', ARRAY['force majeure','applies','FM Event','affects','Key Person','death','incapacity','unavailability','Amazon','elect','recast','role','modify','Program','suspend','pending replacement','terminate','consult','good faith','appropriate response']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Key Person FM with consultation", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Key Person FM handling with consultation is reasonable. Amazon retains decision authority but consultation provides ProdCo input on matters like recasting."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If force majeure affects only a portion of the production, performance of unaffected portions shall continue. The parties shall cooperate to modify the production schedule to accommodate both continued and suspended portions.', ARRAY['force majeure','affects','only','portion','production','performance','unaffected portions','continue','cooperate','modify','production schedule','accommodate','continued','suspended portions']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Partial FM with continued performance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Continued performance of unaffected portions is practical approach. Cooperation on schedule modifications addresses real-world partial disruption scenarios."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Force majeure relief is available. The affected party shall provide: (a) written notice within 48 hours of becoming aware of the FM Event; (b) regular updates on status and expected resolution; and (c) documented evidence of the FM Event and its effects upon request.', ARRAY['force majeure relief','available','affected party','provide','written notice','48 hours','becoming aware','FM Event','regular updates','status','expected resolution','documented evidence','FM Event','effects','request']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "FM notice and documentation requirements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Specific notice timeline, update requirement, and documentation obligation are reasonable procedural requirements for FM claims."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'During an FM Event affecting production, Amazon shall have the option, but not the obligation, to provide resources or assistance to help mitigate the FM Event''s effects. Any such assistance shall not affect the allocation of risk or expense under this Agreement.', ARRAY['during','FM Event','affecting production','Amazon','option','not obligation','provide','resources','assistance','mitigate','FM Event''s effects','assistance','not affect','allocation','risk','expense','Agreement']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Optional Amazon FM assistance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Optional Amazon assistance without obligation or risk reallocation provides flexibility to help while preserving Agreement structure."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Industry-wide labor strikes affecting the film and television industry generally shall be treated as Force Majeure Events. Strikes limited to ProdCo''s employees or specific to ProdCo''s production shall not qualify as Force Majeure.', ARRAY['industry-wide','labor strikes','affecting','film','television industry','generally','Force Majeure Events','strikes','limited','ProdCo''s employees','specific','ProdCo''s production','not qualify','Force Majeure']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Strike FM clarification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Industry-wide versus ProdCo-specific strike distinction is reasonable. General industry strikes are beyond control; ProdCo-specific labor issues are not FM-qualifying."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If Amazon terminates due to extended FM, and subsequently produces a Program substantially based on the terminated Program''s elements within three (3) years, ProdCo shall receive any applicable separation payment per Guild requirements.', ARRAY['Amazon terminates','extended FM','subsequently produces','Program','substantially based','terminated Program''s elements','three years','ProdCo','receive','separation payment','Guild requirements']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "FM termination with subsequent production credit", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Guild separation payment for subsequent production based on terminated elements is reasonable compliance with industry standards."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Force majeure shall excuse ProdCo from all obligations during the FM Event, including payment obligations owed by ProdCo to Amazon and delivery obligations. Amazon shall continue making payments to ProdCo during FM Events regardless of production status.', ARRAY['force majeure','excuse','ProdCo','all obligations','FM Event','including','payment obligations','owed','ProdCo','Amazon','delivery obligations','Amazon','continue','making payments','ProdCo','FM Events','regardless','production status']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "Asymmetric FM obligations", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Asymmetric FM treatment requiring Amazon to continue payments while ProdCo is excused from all obligations is completely unacceptable. FM relief must be reciprocal."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Force Majeure Events include any event that ProdCo, in its reasonable judgment, determines makes performance commercially impracticable or significantly more expensive than anticipated.', ARRAY['Force Majeure Events','include','event','ProdCo','reasonable judgment','determines','performance','commercially impracticable','significantly more expensive','anticipated']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "ProdCo-determined commercial impracticability", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo-determined commercial impracticability as FM is unacceptable. FM must be objective external events, not cost overruns or commercial difficulties."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If an FM Event continues for more than thirty (30) days, ProdCo may terminate this Agreement and receive the full remaining Production Fee as if production had been completed.', ARRAY['FM Event','continues','thirty days','ProdCo','terminate','Agreement','receive','full remaining Production Fee','production completed']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "ProdCo FM termination with full payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo termination right with full payment after only 30 days of FM is completely unacceptable. Amazon should have FM termination rights; payment should be for work performed only."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Force majeure shall include any shortage of personnel, equipment, or facilities needed for production, regardless of whether such shortage is specific to ProdCo or industry-wide.', ARRAY['force majeure','include','shortage','personnel','equipment','facilities','needed','production','regardless','shortage','specific','ProdCo','industry-wide']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "Resource shortage as FM", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Resource shortage as FM regardless of cause would excuse ProdCo for poor planning or resource management. FM must be external unforeseeable events, not resource allocation issues."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon waives any right to terminate for force majeure. During any FM Event, the Agreement shall be suspended but Amazon''s payment obligations shall continue, and the Agreement shall resume upon conclusion of the FM Event without any adjustment.', ARRAY['Amazon waives','right to terminate','force majeure','FM Event','Agreement','suspended','Amazon''s payment obligations','continue','Agreement','resume','conclusion','FM Event','without','adjustment']::text[], '{"doc": "Counterparty_Proposal", "section": "Force Majeure", "note": "No Amazon FM termination with continued payment", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Waiving Amazon''s FM termination right while requiring continued payment is completely one-sided. Amazon must retain FM termination rights, especially for extended events."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Pandemics and epidemics shall not constitute Force Majeure Events regardless of their severity, as such events are now foreseeable in the post-COVID environment.', ARRAY['pandemics','epidemics','not constitute','Force Majeure Events','regardless','severity','events','foreseeable','post-COVID environment']::text[], '{"doc": "Counterparty_Markup", "section": "Force Majeure", "note": "Pandemic exclusion from FM", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Categorical pandemic exclusion regardless of severity is too broad. Future pandemics may still be FM-qualifying events depending on circumstances and government response."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement, together with all exhibits and schedules hereto, constitutes the entire agreement between the parties with respect to the subject matter hereof and supersedes all prior and contemporaneous agreements, understandings, negotiations, and discussions, whether oral or written.', ARRAY['Agreement','exhibits','schedules','constitutes','entire agreement','parties','subject matter','supersedes','prior','contemporaneous','agreements','understandings','negotiations','discussions','oral','written']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Standard entire agreement clause", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard entire agreement clause with merger of prior discussions. Inclusion of exhibits and schedules ensures complete integration."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No amendment, modification, or supplement to this Agreement shall be valid or binding unless made in writing and signed by authorized representatives of both parties. Email and other electronic communications shall not constitute a writing for this purpose.', ARRAY['no amendment','modification','supplement','Agreement','valid','binding','unless','writing','signed','authorized representatives','both parties','email','electronic communications','not constitute','writing']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Written amendment requirement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Strict written amendment requirement with signature prevents informal modification claims. Email exclusion ensures formal process for changes."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'No waiver of any provision of this Agreement shall be effective unless in writing and signed by the waiving party. No waiver shall operate as a waiver of any other provision, and no single waiver shall constitute a continuing or subsequent waiver.', ARRAY['no waiver','provision','Agreement','effective','unless','writing','signed','waiving party','waiver','not operate','waiver','other provision','single waiver','not constitute','continuing','subsequent waiver']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Waiver requirements and limitations", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Written waiver requirement prevents implied waiver claims. Limitations on waiver scope and duration protect against waiver creep."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The failure of either party to enforce any provision of this Agreement shall not constitute a waiver of such provision or the right to enforce it at a later time. Delay in exercising any right shall not constitute waiver of such right.', ARRAY['failure','either party','enforce','provision','Agreement','not constitute','waiver','provision','right to enforce','later time','delay','exercising','right','not constitute','waiver']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Non-waiver for non-enforcement", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Protects against waiver by inaction. Delay protection ensures parties can enforce rights even if not immediately asserted."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Each party acknowledges that it has not relied on any statement, representation, or warranty not expressly set forth in this Agreement. No party shall have any claim against the other for innocent or negligent misrepresentation based on any statement not contained herein.', ARRAY['acknowledges','not relied','statement','representation','warranty','not expressly set forth','Agreement','no party','claim','other','innocent','negligent misrepresentation','statement','not contained']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Non-reliance acknowledgment", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Non-reliance acknowledgment prevents claims based on pre-contractual statements. Limits misrepresentation claims to fraudulent misrepresentation."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'This Agreement may be executed in counterparts, each of which shall be deemed an original, and all of which together shall constitute one and the same instrument. Electronic signatures and PDF copies shall have the same legal effect as original signatures and documents.', ARRAY['Agreement','executed','counterparts','deemed','original','together','constitute','same instrument','electronic signatures','PDF copies','same legal effect','original signatures','documents']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Counterparts and electronic signatures", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Counterparts clause facilitates execution. Electronic signature and PDF recognition is essential for modern transactions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The terms of this Agreement shall control over any conflicting or additional terms in any purchase order, invoice, acknowledgment, or other document. No terms proposed by ProdCo in any other document shall be binding unless expressly agreed in writing by Amazon.', ARRAY['terms','Agreement','control','conflicting','additional terms','purchase order','invoice','acknowledgment','document','terms','proposed','ProdCo','other document','not binding','unless','expressly agreed','writing','Amazon']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "No battle of forms", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Prevailing terms clause prevents ''battle of the forms'' issues. Agreement terms control over any conflicting terms in other documents."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'This Agreement is the entire agreement. The parties agree that Amazon''s standard operating procedures and production guidelines, as updated from time to time and provided to ProdCo, are incorporated by reference and shall be binding without formal amendment.', ARRAY['Agreement','entire agreement','Amazon''s standard operating procedures','production guidelines','updated','time to time','provided','ProdCo','incorporated by reference','binding','without','formal amendment']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Incorporated guidelines without amendment", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Incorporation of Amazon''s SOPs and guidelines allows operational flexibility. Binding without formal amendment may be acceptable if procedures are administrative only."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Amendments require writing signed by both parties. Notwithstanding, amendments to delivery schedules and production budgets may be made by email exchange between authorized production contacts, provided such amendments do not affect material economic terms.', ARRAY['amendments','require','writing','signed','both parties','notwithstanding','amendments','delivery schedules','production budgets','email exchange','authorized production contacts','not affect','material economic terms']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Email amendment for operational matters", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Email amendment exception for schedules and budgets is operationally practical. Material economic terms carveout preserves formal process for significant changes."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'No waiver shall be effective unless in writing. The parties acknowledge that a course of dealing between them shall not constitute waiver or modification of Agreement terms, even if such course of dealing has continued for an extended period.', ARRAY['no waiver','effective','unless','writing','acknowledge','course of dealing','not constitute','waiver','modification','Agreement terms','course of dealing','continued','extended period']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Course of dealing exclusion", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Course of dealing exclusion prevents argument that practices modified the Agreement. Important for long-term relationships with evolving operations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'This is the entire agreement. The parties may establish a formal amendment process through a written protocol identifying authorized amendment signatories, required approvals, and documentation requirements. Such protocol shall itself require formal execution.', ARRAY['entire agreement','establish','formal amendment process','written protocol','identifying','authorized amendment signatories','required approvals','documentation requirements','protocol','require','formal execution']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Amendment protocol option", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Option to establish amendment protocol provides flexibility while requiring formal execution of the protocol itself. Useful for complex ongoing relationships."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Written amendment is required. For purposes of this provision, an amendment signed by Amazon''s VP of Content or above shall be binding on Amazon. ProdCo shall not be bound by amendments signed below the level of ProdCo''s CEO or authorized designee.', ARRAY['written amendment','required','amendment','signed','Amazon''s VP of Content','above','binding','Amazon','ProdCo','not bound','amendments','signed','below','ProdCo''s CEO','authorized designee']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Signing authority specification", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Specification of signing authority levels provides clarity on who can bind each party. May be useful for larger organizations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The entire agreement clause applies. For clarification, the following prior agreements remain in effect and are not superseded: [list specific NDAs, development agreements, or other surviving agreements].', ARRAY['entire agreement','applies','clarification','prior agreements','remain in effect','not superseded','list','specific NDAs','development agreements','surviving agreements']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Carveout for specific prior agreements", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Carveout for specifically listed prior agreements is acceptable when needed to preserve valid prior arrangements. Must be specifically enumerated."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement may be amended by either party providing written notice of the amendment to the other party. If the other party does not object within thirty (30) days, the amendment shall become effective.', ARRAY['Agreement','amended','either party','written notice','amendment','other party','not object','thirty days','amendment','become effective']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Unilateral amendment with deemed consent", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Unilateral amendment with deemed consent for non-objection allows either party to modify the Agreement without actual agreement. Mutual signature is required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Oral amendments shall be binding if made by authorized representatives during production meetings and confirmed in meeting minutes distributed within five (5) business days.', ARRAY['oral amendments','binding','authorized representatives','production meetings','confirmed','meeting minutes','distributed','five business days']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Oral amendments via meeting minutes", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Oral amendments with meeting minute confirmation is too informal for binding contract changes. Signed written amendments are required."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'This Agreement is the entire agreement. However, any written communication from ProdCo setting forth additional terms or conditions shall be deemed an amendment if Amazon does not expressly reject such terms within ten (10) business days.', ARRAY['Agreement','entire agreement','written communication','ProdCo','additional terms','conditions','deemed','amendment','Amazon','not expressly reject','terms','ten business days']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "ProdCo deemed amendment by non-rejection", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "ProdCo one-sided deemed amendment through non-rejection would allow ProdCo to modify Agreement unilaterally. Completely unacceptable."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'The entire agreement clause shall not apply to limit ProdCo''s right to recover damages based on pre-contractual representations made by Amazon during negotiations, regardless of whether such representations are reflected in this Agreement.', ARRAY['entire agreement','not apply','limit','ProdCo''s right','recover damages','pre-contractual representations','Amazon','negotiations','regardless','representations','reflected','Agreement']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Pre-contractual representation carveout", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Carving out pre-contractual representations defeats the entire agreement clause''s purpose. Creates liability for statements outside the contract."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s failure to enforce any provision on three (3) or more occasions shall constitute a permanent waiver of such provision. ProdCo may rely on such waiver as a modification of the Agreement.', ARRAY['Amazon''s failure','enforce','provision','three','more occasions','constitute','permanent waiver','provision','ProdCo','rely','waiver','modification','Agreement']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Automatic waiver after repeated non-enforcement", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Automatic permanent waiver after three non-enforcements would eliminate rights through inaction. No waiver without express written waiver."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Industry custom and practice shall supplement this Agreement. Where this Agreement is silent, industry customs applicable to productions of this type shall govern the parties'' relationship.', ARRAY['industry custom','practice','supplement','Agreement','Agreement','silent','industry customs','applicable','productions','type','govern','parties'' relationship']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Industry custom gap-filler", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Industry custom gap-filler introduces undefined and potentially disputed terms. The Agreement must be complete; gaps should not be filled by custom."}'::jsonb)
    INSERT INTO policy_examples (matter_policy_id, clause_type_id, acceptance, example_text, normalized_terms, source_ref)
    VALUES
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If any provision of this Agreement is held to be invalid, illegal, or unenforceable, such provision shall be modified to the minimum extent necessary to make it valid and enforceable, or if modification is not possible, such provision shall be severed, and the remaining provisions shall remain in full force and effect.', ARRAY['provision','Agreement','held','invalid','illegal','unenforceable','modified','minimum extent','necessary','valid','enforceable','modification','not possible','severed','remaining provisions','full force and effect']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Standard severability with modification", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Standard severability clause with modification preference before severance. Preserves Agreement validity while addressing invalid provisions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Severability shall not apply if the invalid provision is so fundamental to this Agreement that the parties would not have entered into the Agreement without it. In such case, the entire Agreement shall be voidable at the option of either party.', ARRAY['severability','not apply','invalid provision','fundamental','Agreement','parties','not have entered','Agreement','without','entire Agreement','voidable','option','either party']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Fundamental provision exception", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Fundamental provision exception recognizes that some provisions are essential to the bargain. Voidability option provides appropriate exit when core terms fail."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'The following provisions shall survive expiration or termination of this Agreement for any reason: ownership and grant of rights; indemnification; confidentiality; limitation of liability; representations and warranties; and any other provision that by its nature or express terms should survive.', ARRAY['provisions','survive','expiration','termination','Agreement','any reason','ownership','grant of rights','indemnification','confidentiality','limitation of liability','representations','warranties','provision','nature','express terms','survive']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Enumerated survival provisions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Comprehensive enumeration of surviving provisions ensures critical protections continue post-termination. Catch-all for nature-based survival addresses unenumerated provisions."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Survival of obligations shall not be affected by whether termination was for cause, for convenience, by expiration, or by operation of law. Surviving obligations shall continue for the periods specified herein or, if no period is specified, indefinitely.', ARRAY['survival','obligations','not affected','termination','for cause','for convenience','expiration','operation of law','surviving obligations','continue','periods specified','no period','specified','indefinitely']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Survival regardless of termination reason", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Universal survival regardless of termination circumstances ensures protections aren''t lost based on termination type. Indefinite default for unspecified periods provides maximum protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall survive in perpetuity with respect to any claim arising from the Program or Materials delivered hereunder. This survival applies regardless of any termination, expiration, or invalidity of any other provision.', ARRAY['ProdCo''s indemnification','survive','perpetuity','claim','arising from','Program','Materials','delivered','survival applies','regardless','termination','expiration','invalidity','other provision']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Perpetual indemnification survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Perpetual indemnification survival reflects that content claims can arise indefinitely after creation. Survival independent of other provisions ensures this critical protection."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'Amazon''s ownership of the Program and all rights therein shall survive any termination, expiration, or invalidity of this Agreement. Such ownership shall vest and remain with Amazon regardless of any claim by ProdCo arising from the Agreement''s termination.', ARRAY['Amazon''s ownership','Program','rights','survive','termination','expiration','invalidity','Agreement','ownership','vest','remain','Amazon','regardless','claim','ProdCo','arising from','Agreement''s termination']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Ownership survival", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Ownership survival ensures Amazon''s rights persist regardless of Agreement status. Critical protection given Amazon''s investment in content."}'::jsonb),
      (mp_id, ct_id, 'ACCEPTABLE'::acceptance_level, 'If any court or arbitrator reforms or limits any provision affecting Amazon''s rights, Amazon may, at its option, terminate this Agreement upon notice without liability, except for payment for work performed through the termination date.', ARRAY['court','arbitrator','reforms','limits','provision','affecting','Amazon''s rights','Amazon','option','terminate','Agreement','notice','without liability','except','payment','work performed','termination date']::text[], '{"doc": "PSA_Principal_Terms", "section": "General", "note": "Termination right for reformed provisions", "approval": null, "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Termination right when provisions affecting Amazon''s rights are reformed allows exit from unfavorably modified Agreement. Payment for work performed is fair."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Severability applies. If severance of a provision would materially alter the economic bargain, the parties shall negotiate in good faith to restore the economic balance through amendment. If no agreement is reached within thirty (30) days, either party may terminate.', ARRAY['severability','applies','severance','provision','materially alter','economic bargain','negotiate','good faith','restore','economic balance','amendment','no agreement','thirty days','either party','terminate']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Renegotiation for material severance", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Renegotiation obligation for material economic impact with termination fallback is reasonable approach to significant severance situations."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Surviving provisions shall remain effective. For purposes of clarity, the following provisions shall expressly survive: Sections [X] (Ownership), [Y] (Indemnification), [Z] (Confidentiality), [AA] (Limitation of Liability), [BB] (Dispute Resolution), and [CC] (Representations).', ARRAY['surviving provisions','remain effective','clarity','provisions','expressly survive','Sections','Ownership','Indemnification','Confidentiality','Limitation of Liability','Dispute Resolution','Representations']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Section-specific survival enumeration", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Section-specific enumeration provides clarity on exactly which provisions survive. Cross-referenced to specific sections for precision."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Confidentiality obligations shall survive for five (5) years after termination. Indemnification obligations shall survive for seven (7) years after termination. Ownership provisions shall survive indefinitely.', ARRAY['confidentiality obligations','survive','five years','after termination','indemnification obligations','survive','seven years','after termination','ownership provisions','survive','indefinitely']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Tiered survival periods", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Tiered survival periods by provision type may be acceptable. Five years for confidentiality is minimum; seven for indemnification addresses claim discovery periods; indefinite ownership is essential."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'The rights and obligations of the parties with respect to completed episodes and deliverables shall survive termination. Rights and obligations with respect to uncommenced work shall terminate as of the termination date.', ARRAY['rights','obligations','parties','completed episodes','deliverables','survive','termination','rights','obligations','uncommenced work','terminate','termination date']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Completed versus uncommenced work distinction", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "MEDIUM", "reasoning": "Distinction between completed and uncommenced work is practical approach. Completed work rights survive; uncommenced work obligations appropriately terminate."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'If any provision is held invalid in a particular jurisdiction, such invalidity shall not affect the validity of such provision in any other jurisdiction. Provisions shall be severed on a jurisdiction-by-jurisdiction basis to the extent possible.', ARRAY['provision','held invalid','particular jurisdiction','invalidity','not affect','validity','provision','other jurisdiction','provisions','severed','jurisdiction-by-jurisdiction basis','extent possible']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Jurisdiction-specific severability", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Jurisdiction-specific severability prevents invalidity in one jurisdiction from affecting enforceability elsewhere. Practical for international productions."}'::jsonb),
      (mp_id, ct_id, 'PASSABLE'::acceptance_level, 'Survival provisions shall bind successors and assigns. If Amazon assigns this Agreement, the assignee shall have the benefit of all surviving provisions, and ProdCo''s surviving obligations shall extend to such assignee.', ARRAY['survival provisions','bind','successors','assigns','Amazon assigns','Agreement','assignee','benefit','surviving provisions','ProdCo''s surviving obligations','extend','assignee']::text[], '{"doc": "Counterparty_Markup", "section": "General", "note": "Survival extends to assignees", "approval": "AMAZON_LEGAL", "jurisdiction": "US", "risk_level": "LOW", "reasoning": "Extension of survival to assignees ensures continuing protections transfer with the Agreement. Essential for meaningful assignment rights."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If any provision is found invalid, the entire Agreement shall be void and unenforceable, and ProdCo shall have no further obligations to Amazon, including with respect to rights previously granted.', ARRAY['provision','found invalid','entire Agreement','void','unenforceable','ProdCo','no further obligations','Amazon','including','rights','previously granted']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Whole Agreement void for any invalidity", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Voiding entire Agreement for any provision invalidity is completely unacceptable. Would allow ProdCo to escape obligations if any minor provision fails."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'ProdCo''s indemnification obligations shall not survive termination for more than two (2) years. After such period, ProdCo shall have no further indemnification liability regardless of when claims arise.', ARRAY['ProdCo''s indemnification','not survive','termination','more than','two years','after period','no further','indemnification liability','regardless','when','claims arise']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Two-year indemnification survival limit", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Two-year indemnification survival is grossly inadequate. Content claims can arise decades after creation. Indemnification must survive indefinitely."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Amazon''s ownership of the Program shall survive termination for cause by Amazon. If Amazon terminates for convenience or ProdCo terminates for Amazon''s breach, all rights shall revert to ProdCo.', ARRAY['Amazon''s ownership','Program','survive','termination for cause','Amazon','Amazon terminates','convenience','ProdCo terminates','Amazon''s breach','all rights','revert','ProdCo']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Conditional ownership survival with reversion", "approval": null, "jurisdiction": "US", "risk_level": "CRITICAL", "reasoning": "Conditional ownership survival with reversion for convenience termination or breach is completely unacceptable. Amazon''s ownership must be absolute and unconditional."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Survival provisions shall be mutual. Amazon''s obligations, including payment obligations, shall survive to the same extent and for the same periods as ProdCo''s obligations.', ARRAY['survival provisions','mutual','Amazon''s obligations','including','payment obligations','survive','same extent','same periods','ProdCo''s obligations']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Forced mutual survival", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Forced mutual survival ignores asymmetric nature of obligations. ProdCo''s content-related obligations appropriately have longer survival than Amazon''s payment obligations."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'Upon termination, all provisions shall terminate except those expressly designated as surviving in this Section. No provision shall survive by implication, nature, or prior course of dealing.', ARRAY['termination','all provisions','terminate','except','expressly designated','surviving','Section','no provision','survive','implication','nature','prior course of dealing']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "No implied survival", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Eliminating nature-based survival could exclude important provisions not expressly listed. Survival by nature is standard and necessary for comprehensive protection."}'::jsonb),
      (mp_id, ct_id, 'UNACCEPTABLE'::acceptance_level, 'If any limitation of liability or exclusion of damages provision is found unenforceable, the corresponding provision limiting ProdCo''s liability or excluding damages for ProdCo''s benefit shall also be deemed unenforceable.', ARRAY['limitation of liability','exclusion of damages','provision','unenforceable','corresponding provision','limiting','ProdCo''s liability','excluding damages','ProdCo''s benefit','deemed unenforceable']::text[], '{"doc": "Counterparty_Proposal", "section": "General", "note": "Linked unenforceability", "approval": null, "jurisdiction": "US", "risk_level": "HIGH", "reasoning": "Linked unenforceability would void Amazon''s limitations if ProdCo''s fail. Severability should operate independently for each provision."}'::jsonb)
