-- 20260120061000_seed_harvey_policy_examples_expanded.sql
-- Harvey Dataset: 1,282 policy_examples for RAG
-- Generated from harvey_policy_examples_db_ready.jsonl
-- Idempotent: uses ON CONFLICT DO NOTHING

DO $$
DECLARE
  org_id uuid;
  bp_version_id uuid;
  mp_id uuid;
  ct_id uuid;
BEGIN
  -- Get org
  SELECT id INTO org_id
  FROM organizations
  ORDER BY created_at ASC
  LIMIT 1;

  -- Get blueprint version
  SELECT rbv.id INTO bp_version_id
  FROM review_blueprint_versions rbv
  JOIN review_blueprints rb ON rb.id = rbv.blueprint_id
  WHERE rb.organization_id = org_id
    AND rb.name LIKE '%Amazon%'
    AND rbv.version_int = 1
  LIMIT 1;

  IF bp_version_id IS NULL THEN
    RAISE EXCEPTION 'Blueprint version not found. Run taxonomy seeds first.';
  END IF;


  



  -- dispute_resolution / injunctive_relief_preservation (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'dispute_resolution'
    AND ct.code = 'injunctive_relief_preservation';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- dispute_resolution / escalation_and_informal_resolution (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'dispute_resolution'
    AND ct.code = 'escalation_and_informal_resolution';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- miscellaneous_provisions / assignment_and_transfer_restrictions (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'miscellaneous_provisions'
    AND ct.code = 'assignment_and_transfer_restrictions';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- miscellaneous_provisions / notices_and_communications (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'miscellaneous_provisions'
    AND ct.code = 'notices_and_communications';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- miscellaneous_provisions / force_majeure (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'miscellaneous_provisions'
    AND ct.code = 'force_majeure';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- miscellaneous_provisions / entire_agreement_amendments_waivers (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'miscellaneous_provisions'
    AND ct.code = 'entire_agreement_amendments_waivers';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  -- miscellaneous_provisions / severability_and_survival (19 records)
  SELECT mp.id, ct.id INTO mp_id, ct_id
  FROM matter_policies mp
  JOIN matters m ON m.id = mp.matter_id
  JOIN clause_types ct ON ct.matter_id = m.id
  WHERE mp.blueprint_version_id = bp_version_id
    AND m.code = 'miscellaneous_provisions'
    AND ct.code = 'severability_and_survival';

  IF mp_id IS NOT NULL AND ct_id IS NOT NULL THEN
    ON CONFLICT DO NOTHING;
  END IF;



  RAISE NOTICE 'Harvey policy_examples seeded successfully';
END IF;

END $$;